.scroll-area { height: 150vh; width: 100%; display: flex; flex-direction: column; align-items: center; }
.reveal-text-wrap { display: flex; gap: 8px; margin-top: 60vh; overflow: hidden; }
.char {
  font-size: 45px; font-weight: 900; color: transparent; font-family: sans-serif;
  -webkit-text-stroke: 1px #fff;
  transform: translateY(100px) rotate(20deg); opacity: 0;
  transition: transform 0.6s cubic-bezier(0.175, 0.885, 0.32, 1.275), opacity 0.6s, color 0.4s;
}
.char.visible { transform: translateY(0) rotate(0deg); opacity: 1; }
.char.visible:hover { color: #ff007f; -webkit-text-stroke: 1px #ff007f; transform: scale(1.2) translateY(-10px); }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:transparent;';

const area = document.createElement('div');
area.className = 'scroll-area';
area.innerHTML = '<div style="color:#555; margin-top:20px;">SCROLL DOWN ↓</div>';

const wrap = document.createElement('div');
wrap.className = 'reveal-text-wrap';

const word = "AWESOME";
const chars = [];
word.split('').forEach((letter, i) => {
  const span = document.createElement('div');
  span.className = 'char';
  span.innerText = letter;
  span.style.transitionDelay = `${i * 0.1}s`; // GSAP Stagger effect
  chars.push(span);
  wrap.appendChild(span);
});

area.appendChild(wrap); c.appendChild(area);

const observer = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if(entry.isIntersecting) {
      chars.forEach(ch => ch.classList.add('visible'));
    } else {
      chars.forEach(ch => ch.classList.remove('visible'));
    }
  });
}, { threshold: 0.5 });
observer.observe(wrap);
